graphql.query:
query Search($input: HotelSearchInput) {
  hotels(input: $input) {
    total
    page
    size
    items { id name city countryCode starRating fromPricePerNight }
  }
}

query Hotel($id: ID!) {
  hotel(id: $id) {
    name
    city
    checkInTime
    checkOutTime
    fromPricePerNight
    media { url }
    amenities { name }
    roomTypes { id name maxAdults pricePerNight }
  }
}

query Details($id: ID!) {
  hotelDetails(id: $id) {
    hotel { name city }
    experiences { name }
    restaurants { name }
    reviewsCount
    averageRating
    reviews { total items { authorName rating title } }
  }
}

query Offers($hotelId: ID!) {
  offers(hotelId: $hotelId) { code name discountType discountValue }
  extras(hotelId: $hotelId) { name pricePerUnit }
  reviews(hotelId: $hotelId) { total items { rating title } }
}

query Availability($input: AvailabilityInput!) {
  availability(input: $input) { roomTypeId status available capacityFits }
}

query Rates($input: RatesInput!) {
  rates(input: $input) { roomTypeId ratePlanId ratePlanCode pricePerNight }
}

query Quote($input: QuoteInput!) {
  quote(input: $input) {
    currencyCode
    subtotalAmount
    discountAmount
    taxAmount
    feeAmount
    totalAmount
    originalTotal
    valid
    message
    lines { roomTypeId ratePlanId ratePerNight nights subtotalAmount }
  }
}

mutation Register($input: RegisterInput!) {
  register(input: $input) { token me { id email roles hotelIds } }
}

mutation Login($input: LoginInput!) {
  login(input: $input) { token me { id email roles hotelIds } }
}

mutation Book($input: CreateReservationInput!) {
  createReservation(input: $input) {
    created
    reservation {
      id reference status paymentStatus checkInDate checkOutDate totalAmount
      roomLines { roomTypeId ratePlanId nights ratePerNight subtotalAmount }
    }
  }
}

query Lookup($input: ReservationLookupInput!) {
  reservation(input: $input) {
    reference status paymentStatus checkInDate checkOutDate totalAmount
    guest { firstName lastName email }
  }
}

mutation Cancel($input: CancelReservationInput!) {
  cancelReservation(input: $input) {
    reservation {
      reference status
      cancellation { penaltyAmount refundAmount refundable reason }
    }
  }
}

mutation Pay($input: CreatePaymentInput!) {
  createPayment(input: $input) { id reservationId amount currencyCode status provider }
}

mutation Capture($input: CapturePaymentInput!) {
  capturePayment(input: $input) { id status providerReference }
}

mutation Bill($input: ReservationLookupInput!) {
  issueInvoice(input: $input) {
    invoiceNumber billingName totalAmount
    items { description quantity unitPrice totalPrice }
  }
}

mutation Review($input: CreateReviewInput!) {
  createReview(input: $input) { id rating title comment moderationStatus }
}

query AdminHotel($hotelId: ID!) {
  adminHotel(hotelId: $hotelId) {
    name status
    roomTypes { id name maxAdults }
    ratePlans { id code name pricePerNight }
    availability { roomTypeId stayDate totalInventory roomsSold }
  }
}

query AdminReservations($hotelId: ID!, $status: ReservationStatus, $page: PageInput) {
  adminReservations(hotelId: $hotelId, status: $status, page: $page) {
    total page size
    items { reference status paymentStatus checkInDate totalAmount }
  }
}

mutation Login($input: LoginInput!) {
  login(input: $input) { token me { id email roles hotelIds } }
}

query Me {
  me { id email firstName lastName roles hotelIds }
}

query Dashboard($hotelId: ID!) {
  adminDashboard(hotelId: $hotelId) {
    hotelName arrivalsToday departuresToday inHouseToday soldOutTonight
    occupancyPct revenueTotal pendingPayments pendingInvoices availableTonight
  }
}

query Hotels($page: PageInput) {
  adminHotels(page: $page) { total page size items { id name brand city countryCode starRating status roomTypeCount activeReservations } }
}

query Workspace($hotelId: ID!) {
  adminHotel(hotelId: $hotelId) {
    hotel { id name status }
    amenities { id name }
    media { id url isPrimary }
    roomTypes { id name status }
    rooms { id roomNumber status }
    ratePlans { id name status links { id roomTypeName prices { validFrom validTo priceAmount } } }
    availability { id stayDate totalInventory sold outOfOrder blocked }
  }
}

mutation CreateHotel($input: AdminHotelInput!) {
  createHotel(input: $input) { id name status }
}

mutation CreateRoomType($hotelId: ID!, $input: AdminRoomTypeInput!) {
  createRoomType(hotelId: $hotelId, input: $input) { id name }
}

mutation CreateRoom($hotelId: ID!, $input: AdminRoomInput!) {
  createRoom(hotelId: $hotelId, input: $input) { id roomNumber status }
}

mutation CreateRatePlan($hotelId: ID!, $input: AdminRatePlanInput!) {
  createRatePlan(hotelId: $hotelId, input: $input) { id name code }
}

mutation Link($roomTypeId: ID!, $ratePlanId: ID!) {
  linkRoomTypeRatePlan(roomTypeId: $roomTypeId, ratePlanId: $ratePlanId) { id }
}

mutation SetPrices($linkId: ID!, $prices: [RatePlanPriceInput!]!) {
  setRatePlanPrices(linkId: $linkId, prices: $prices) { id }
}

query Amenities {
  adminAmenities { id name category }
}

query Reservations($hotelId: ID!, $page: PageInput) {
  adminReservations(hotelId: $hotelId, page: $page) {
    total items { id reference status paymentStatus checkInDate checkOutDate totalAmount guest { firstName lastName } }
  }
}

query Guests($hotelId: ID!, $query: String, $page: PageInput) {
  adminGuests(hotelId: $hotelId, query: $query, page: $page) { total items { id firstName lastName email phone } }
}

query Payments($hotelId: ID!, $page: PageInput) {
  adminPayments(hotelId: $hotelId, page: $page) { total items { id amount currencyCode status provider } }
}

query Invoices($hotelId: ID!, $page: PageInput) {
  adminInvoices(hotelId: $hotelId, page: $page) { total items { id invoiceNumber totalAmount status } }
}

query Promotions($hotelId: ID!) {
  adminPromotions(hotelId: $hotelId) { id code name discountType discountValue status }
}

query Reviews($hotelId: ID!, $page: PageInput) {
  adminReviews(hotelId: $hotelId, page: $page) { total items { id rating title status } }
}

query Notifications($hotelId: ID!, $page: PageInput) {
  adminNotifications(hotelId: $hotelId, page: $page) { total items { id type message isRead createdAt } }
}

query Users {
  adminUsers(page: { page: 0, size: 50 }) { total items { id email firstName lastName status roles { roleName hotelName } } }
  adminRoles { id name description }
}

query Audit($page: PageInput) {
  adminAuditLogs(page: $page) { total items { id actorEmail action entityType entityId createdAt } }
}

query PlatformBySlug($slug: String!) {
  platform(slug: $slug) {
    id
    slug
    name
    tagline
    description
    status
    media { id url altText category isPrimary }
    contentBlocks {
      __typename
      id
      type
      position
      isEnabled
      ... on HeroBlock {
        eyebrow
        title
        subtitle
        image { id url altText }
        mobileImage { id url altText }
        ctaLabel
        ctaTarget
      }
      ... on FeaturedExperiencesBlock {
        title
        items {
          id
          position
          experience {
            id
            hotelId
            name
            description
            category
            durationMinutes
            priceAmount
            currencyCode
            location
            sortOrder
          }
        }
      }
    }
  }
}
